begin;
set local lock_timeout='5s';set local statement_timeout='30s';
alter table djm_os.club_needs
 add column source_organisation_id uuid references djm_os.organisations(id) on delete set null,
 add column received_date_confirmed boolean not null default false,
 add column level_requirements text;
create index club_needs_source_organisation_idx on djm_os.club_needs(source_organisation_id,tenant_id);
create function private.platform_create_club_need_for_record(p_tenant_id uuid,p_actor_user_id uuid,p_organisation_id uuid,p_position text,p_title text,p_notes text,p_expires_on date)
returns jsonb language plpgsql security invoker set search_path='' as $record$
declare
  v_position text := nullif(btrim(coalesce(p_position, '')), '');
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
  v_notes text := nullif(btrim(coalesce(p_notes, '')), '');
  v_org_id uuid := p_organisation_id;
  v_need_id uuid;
  v_expires_at timestamptz;
begin
  perform private.platform_server_assert_agency_operator(
    p_tenant_id,
    p_actor_user_id
  );
  -- Agency operator membership above is the canonical authorisation boundary.

  if v_position is null then
    raise exception 'position_required';
  end if;

  if length(coalesce(v_notes, '')) > 4000 then
    raise exception 'notes_too_long';
  end if;

  if not exists(select 1 from djm_os.organisations o where o.id=v_org_id and o.tenant_id=p_tenant_id and o.organisation_type='club' and o.archived_at is null) then
    raise exception 'Choose an available club in this agency';
  end if;

  if p_expires_on is not null then
    v_expires_at := (p_expires_on + 1)::timestamptz - interval '1 second';
  end if;

  insert into djm_os.club_needs (
    tenant_id,
    organisation_id,
    owner_user_id,
    title,
    position,
    profile_notes,
    raw_request,
    source_context,
    status,
    confidence,
    confirmed_at,
    received_at,
    priority,
    need_type,
    expires_at
  )
  values (
    p_tenant_id,
    v_org_id,
    p_actor_user_id,
    coalesce(v_title, v_position || ' requirement'),
    v_position,
    v_notes,
    v_notes,
    'Agency workspace',
    'active',
    1,
    now(),
    now(),
    3,
    'confirmed',
    v_expires_at
  )
  returning id into v_need_id;

  insert into djm_os.events (
    tenant_id,
    event_type,
    actor_user_id,
    organisation_id,
    payload,
    source,
    confidence,
    occurred_at
  )
  values (
    p_tenant_id,
    'CLUB_NEED_CREATED',
    p_actor_user_id,
    v_org_id,
    jsonb_build_object(
      'club_need_id', v_need_id,
      'position', v_position,
      'source', 'agency_workspace'
    ),
    'agency_workspace',
    1,
    now()
  );

  insert into platform.audit_events (
    tenant_id,
    actor_user_id,
    actor_kind,
    action,
    entity_type,
    entity_id,
    after_state,
    metadata
  )
  values (
    p_tenant_id,
    p_actor_user_id,
    'user',
    'platform.agency.club_need_created',
    'club_need',
    v_need_id::text,
    jsonb_build_object(
      'organisation_id', v_org_id,
      'position', v_position,
      'title', coalesce(v_title, v_position || ' requirement')
    ),
    jsonb_build_object('source', 'agency_workspace')
  );

  return jsonb_build_object(
    'club_need_id', v_need_id,
    'organisation_id', v_org_id,
    'created', true
  );
end;
$record$;
revoke all on function private.platform_create_club_need_for_record(uuid,uuid,uuid,text,text,text,date) from public,anon,authenticated,service_role;

create function public.platform_server_club_request_options(p_tenant_id uuid,p_actor_user_id uuid,p_kind text,p_query text default '',p_selected_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $options$
declare result jsonb;
begin
 if not private.user_is_tenant_admin(p_tenant_id,p_actor_user_id) then raise exception 'Agency administrator access required' using errcode='42501';end if;
 if p_kind is null or p_kind not in ('club','contact','organisation') or length(coalesce(p_query,''))>200 then raise exception 'Check the record search';end if;
 with records as (
  select o.id,o.name,concat_ws(' · ',o.country,o.league_name) detail,o.country,o.league_name
  from djm_os.organisations o where o.tenant_id=p_tenant_id and o.archived_at is null and (p_kind='organisation' or (p_kind='club' and o.organisation_type='club'))
  union all
  select p.id,p.full_name,coalesce((select string_agg(distinct o.name,' · ' order by o.name) from djm_os.employments e join djm_os.organisations o on o.id=e.organisation_id and o.tenant_id=e.tenant_id and o.archived_at is null where e.person_id=p.id and e.tenant_id=p_tenant_id and e.is_current),'Contact'),p.country,null
  from djm_os.people p where p_kind='contact' and p.tenant_id=p_tenant_id and p.archived_at is null and coalesce(p.person_type,'contact')<>'player'
 ), matching as (select * from records where position(lower(trim(coalesce(p_query,''))) in lower(name||' '||coalesce(detail,'')))>0 order by lower(name),id limit 31)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(x) order by lower(x.name),x.id) from (select * from matching order by lower(name),id limit 30) x),'[]'::jsonb),'has_more',(select count(*)>30 from matching),'selected',(select to_jsonb(r) from records r where r.id=p_selected_id)) into result;
 return result;
end $options$;
revoke all on function public.platform_server_club_request_options(uuid,uuid,text,text,uuid) from public,anon,authenticated;
grant execute on function public.platform_server_club_request_options(uuid,uuid,text,text,uuid) to service_role;

-- Guard the exact installed bodies. Preserve existing function identity/metadata/grants.
do $patch$
declare spec jsonb; routine regprocedure; definition text;
begin
 for spec in select value from jsonb_array_elements($spec$[{"signature": "public.platform_server_agency_create_club_need(uuid,uuid,text,text,text,text,text,date)", "hash": "71def288854195f8827a36ed173e5abb", "definition": "CREATE OR REPLACE FUNCTION public.platform_server_agency_create_club_need(p_tenant_id uuid, p_actor_user_id uuid, p_club_name text, p_country text, p_position text, p_title text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_expires_on date DEFAULT NULL::date)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare org uuid; matches integer;\nbegin\n perform private.platform_server_assert_agency_operator(p_tenant_id,p_actor_user_id);\n perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||lower(trim(coalesce(p_club_name,''))),0));\n select count(*) into matches from djm_os.organisations o where o.tenant_id=p_tenant_id and o.organisation_type='club' and o.archived_at is null and lower(trim(o.name))=lower(trim(p_club_name));\n if matches>1 then raise exception 'More than one club has this name. Choose the existing club record';end if;\n if matches=1 then select id into org from djm_os.organisations o where o.tenant_id=p_tenant_id and o.organisation_type='club' and o.archived_at is null and lower(trim(o.name))=lower(trim(p_club_name));\n else\n  if exists(select 1 from djm_os.organisations o where o.tenant_id=p_tenant_id and lower(trim(o.name))=lower(trim(p_club_name)) and o.organisation_type='club' and o.archived_at is not null) then raise exception 'This club is archived. Choose an active club record';end if;\n  org:=private.platform_server_agency_ensure_club(p_tenant_id,p_club_name,p_country);\n end if;\n return private.platform_create_club_need_for_record(p_tenant_id,p_actor_user_id,org,p_position,p_title,p_notes,p_expires_on);\nend;\n$function$\n"}, {"signature": "private.platform_club_need_brief_patch(uuid,uuid,jsonb)", "hash": "faf7f16d83256c2e8a5b34b62e3710cd", "definition": "CREATE OR REPLACE FUNCTION private.platform_club_need_brief_patch(p_tenant_id uuid, p_need_id uuid, p_patch jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\ndeclare n djm_os.club_needs%rowtype; merged jsonb; k text; val text; digits integer; code text; nationalities text[];\nbegin\n if jsonb_typeof(p_patch) is distinct from 'object' then raise exception 'Check the request details'; end if;\n select * into n from djm_os.club_needs where id=p_need_id and tenant_id=p_tenant_id and archived_at is null for update;\n if not found then raise exception 'This club request is unavailable'; end if;\n merged:=to_jsonb(n)||p_patch;\n code:=upper(nullif(trim(merged->>'currency'),''));\n if p_patch?'currency' and code is not null and private.invoice_currency_minor_unit_v1(code) is null then raise exception 'Choose a valid three-letter currency, or leave it blank'; end if;\n foreach k in array array['salary_budget','transfer_budget'] loop\n  if p_patch?k or p_patch?'currency' then\n   val:=nullif(trim(merged->>k),''); digits:=coalesce(private.invoice_currency_minor_unit_v1(code),4);\n   if val is not null and (val!~'^[0-9]{1,12}(\\.[0-9]{1,4})?$' or length(coalesce(split_part(val,'.',2),''))>digits) then raise exception 'Check the salary or transfer fee budget and currency precision'; end if;\n  end if;\n end loop;\n foreach k in array array['contract_months','option_months'] loop\n  val:=nullif(trim(merged->>k),'');\n  if p_patch?k and val is not null and (val!~'^[0-9]{1,3}$' or val::integer not between 1 and 120) then raise exception 'Contract and extension terms must be between 1 and 120 months'; end if;\n end loop;\n if p_patch?'salary_period' and coalesce(nullif(p_patch->>'salary_period',''),'monthly') not in ('monthly','weekly','annual') then raise exception 'Check the salary period'; end if;\n if p_patch?'salary_tax_basis' and coalesce(nullif(p_patch->>'salary_tax_basis',''),'gross') not in ('gross','net') then raise exception 'Check the tax basis'; end if;\n if p_patch?'transfer_type' and coalesce(nullif(p_patch->>'transfer_type',''),'free_agent') not in ('free_agent','permanent','loan') then raise exception 'Check the transfer preference'; end if;\n if p_patch?'source_status' and coalesce(nullif(p_patch->>'source_status',''),'unverified') not in ('confirmed','reported','unverified') then raise exception 'Check the source status'; end if;\n if p_patch?'contract_guaranteed' and coalesce(nullif(p_patch->>'contract_guaranteed',''),'true') not in ('true','false') then raise exception 'Check the contract guarantee'; end if;\n if (p_patch?'contract_guaranteed' or p_patch?'contract_months') and nullif(merged->>'contract_guaranteed','') is not null and nullif(merged->>'contract_months','') is null then raise exception 'Add the initial contract term before recording its guarantee'; end if;\n if p_patch?'availability_notes' and length(p_patch->>'availability_notes')>2000 then raise exception 'Keep availability details within 2,000 characters'; end if;\n\n foreach k in array array['min_age','max_age','min_height_cm','priority'] loop\n  val:=nullif(trim(merged->>k),'');\n  if p_patch?k and val is not null and (val!~'^[0-9]{1,3}$' or val::integer not between (case when k='min_height_cm' then 140 else 1 end) and (case when k='min_height_cm' then 230 when k='priority' then 5 else 99 end)) then raise exception 'Check age, height and priority';end if;\n end loop;\n if (p_patch?'min_age' or p_patch?'max_age') and nullif(merged->>'min_age','')::integer>nullif(merged->>'max_age','')::integer then raise exception 'Minimum age must not exceed maximum age';end if;\n if p_patch?'preferred_foot' and coalesce(nullif(p_patch->>'preferred_foot',''),'left') not in ('left','right','both') then raise exception 'Check the preferred foot';end if;\n foreach k in array array['level_requirements','passport_requirements','registration_notes','foreign_player_notes','playing_style','source_context'] loop\n  if p_patch?k and length(p_patch->>k)>2000 then raise exception 'Keep request details within 2,000 characters';end if;\n end loop;\n if length(p_patch->>'secondary_position')>200 then raise exception 'Shorten the other suitable positions';end if;\n if p_patch?'source_person_id' and nullif(p_patch->>'source_person_id','') is not null and not exists(select 1 from djm_os.people p where p.id=(p_patch->>'source_person_id')::uuid and p.tenant_id=p_tenant_id and p.archived_at is null and coalesce(p.person_type,'contact')<>'player') then raise exception 'Choose an available source contact in this agency';end if;\n if p_patch?'source_organisation_id' and nullif(p_patch->>'source_organisation_id','') is not null and not exists(select 1 from djm_os.organisations o where o.id=(p_patch->>'source_organisation_id')::uuid and o.tenant_id=p_tenant_id and o.archived_at is null) then raise exception 'Choose an available source organisation in this agency';end if;\n if p_patch?'received_on' and nullif(p_patch->>'received_on','') is not null and (p_patch->>'received_on'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or to_char((p_patch->>'received_on')::date,'YYYY-MM-DD')<>p_patch->>'received_on') then raise exception 'Choose a valid date received';end if;\n if p_patch?'nationality_preferences' then\n  if jsonb_typeof(p_patch->'nationality_preferences') not in ('string','array','null') then raise exception 'Check nationality preferences';end if;\n  if jsonb_typeof(p_patch->'nationality_preferences')='array' and exists(select 1 from jsonb_array_elements(p_patch->'nationality_preferences') a where jsonb_typeof(a)<>'string') then raise exception 'Check nationality preferences';end if;\n  select coalesce(array_agg(v order by ord),'{}'::text[]) into nationalities from (\n   select trim(value) v,ord from jsonb_array_elements_text(case when jsonb_typeof(p_patch->'nationality_preferences')='array' then p_patch->'nationality_preferences' else to_jsonb(string_to_array(replace(coalesce(p_patch->>'nationality_preferences',''),E'\\r',''),E'\\n')) end) with ordinality a(value,ord) where trim(value)<>''\n  ) x;\n  if cardinality(nationalities)>30 or length(array_to_string(nationalities,E'\\n'))>2000 or exists(select 1 from unnest(nationalities) value where length(value)>100) then raise exception 'Shorten nationality preferences';end if;\n end if;\n update djm_os.club_needs set\n  secondary_position=case when p_patch?'secondary_position' then nullif(trim(p_patch->>'secondary_position'),'') else secondary_position end,\n  min_age=case when p_patch?'min_age' then nullif(p_patch->>'min_age','')::smallint else min_age end,\n  max_age=case when p_patch?'max_age' then nullif(p_patch->>'max_age','')::smallint else max_age end,\n  min_height_cm=case when p_patch?'min_height_cm' then nullif(p_patch->>'min_height_cm','')::smallint else min_height_cm end,\n  preferred_foot=case when p_patch?'preferred_foot' then nullif(p_patch->>'preferred_foot','') else preferred_foot end,\n  level_requirements=case when p_patch?'level_requirements' then nullif(trim(p_patch->>'level_requirements'),'') else level_requirements end,\n  nationality_preferences=case when p_patch?'nationality_preferences' then nationalities else nationality_preferences end,\n  passport_requirements=case when p_patch?'passport_requirements' then nullif(trim(p_patch->>'passport_requirements'),'') else passport_requirements end,\n  registration_notes=case when p_patch?'registration_notes' then nullif(trim(p_patch->>'registration_notes'),'') else registration_notes end,\n  foreign_player_notes=case when p_patch?'foreign_player_notes' then nullif(trim(p_patch->>'foreign_player_notes'),'') else foreign_player_notes end,\n  playing_style=case when p_patch?'playing_style' then nullif(trim(p_patch->>'playing_style'),'') else playing_style end,\n  source_person_id=case when p_patch?'source_person_id' then nullif(p_patch->>'source_person_id','')::uuid else source_person_id end,\n  source_organisation_id=case when p_patch?'source_organisation_id' then nullif(p_patch->>'source_organisation_id','')::uuid else source_organisation_id end,\n  received_at=case when p_patch?'received_on' and nullif(p_patch->>'received_on','') is not null then (p_patch->>'received_on')::date::timestamptz else received_at end,\n  received_date_confirmed=case when p_patch?'received_on' then nullif(p_patch->>'received_on','') is not null else received_date_confirmed end,\n  priority=case when p_patch?'priority' then coalesce(nullif(p_patch->>'priority','')::smallint,3) else priority end,\n  source_context=case when p_patch?'source_context' then nullif(trim(p_patch->>'source_context'),'') else source_context end,\n\n  salary_budget=case when p_patch?'salary_budget' then nullif(trim(p_patch->>'salary_budget'),'')::numeric else salary_budget end,\n  transfer_budget=case when p_patch?'transfer_budget' then nullif(trim(p_patch->>'transfer_budget'),'')::numeric else transfer_budget end,\n  currency=case when p_patch?'currency' then code else currency end,\n  salary_period=case when p_patch?'salary_period' then nullif(p_patch->>'salary_period','') else salary_period end,\n  salary_tax_basis=case when p_patch?'salary_tax_basis' then nullif(p_patch->>'salary_tax_basis','') else salary_tax_basis end,\n  contract_months=case when p_patch?'contract_months' then nullif(p_patch->>'contract_months','')::smallint else contract_months end,\n  contract_guaranteed=case when p_patch?'contract_guaranteed' then nullif(p_patch->>'contract_guaranteed','')::boolean else contract_guaranteed end,\n  option_months=case when p_patch?'option_months' then nullif(p_patch->>'option_months','')::smallint else option_months end,\n  transfer_type=case when p_patch?'transfer_type' then nullif(p_patch->>'transfer_type','') else transfer_type end,\n  availability_notes=case when p_patch?'availability_notes' then nullif(trim(p_patch->>'availability_notes'),'') else availability_notes end,\n  source_status=case when p_patch?'source_status' then nullif(p_patch->>'source_status','') else source_status end,\n  confirmed_at=case when p_patch?'source_status' then case when p_patch->>'source_status'='confirmed' then coalesce(confirmed_at,now()) else null end else confirmed_at end,\n  updated_at=now()\n where id=p_need_id and tenant_id=p_tenant_id;\nend $function$\n"}, {"signature": "public.platform_server_agency_create_club_need_brief(uuid,uuid,jsonb)", "hash": "0c5fcd622de2c2a7683baee7cd1ad5f6", "definition": "CREATE OR REPLACE FUNCTION public.platform_server_agency_create_club_need_brief(p_tenant_id uuid, p_actor_user_id uuid, p_request jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare created jsonb; brief jsonb;\nbegin\n perform private.platform_server_assert_agency_operator(p_tenant_id,p_actor_user_id);\n if jsonb_typeof(p_request) is distinct from 'object' then raise exception 'Check the club request'; end if;\n brief:=coalesce(p_request->'brief','{}'::jsonb);\n if jsonb_typeof(brief) is distinct from 'object' or exists(select 1 from jsonb_object_keys(brief) k where k not in ('salary_budget','transfer_budget','currency','salary_period','salary_tax_basis','contract_months','contract_guaranteed','option_months','transfer_type','availability_notes','source_status','secondary_position','min_age','max_age','preferred_foot','min_height_cm','level_requirements','nationality_preferences','passport_requirements','registration_notes','foreign_player_notes','playing_style','source_person_id','source_organisation_id','received_on','priority','source_context')) then raise exception 'Refresh ReDream before saving these request details'; end if;\n if nullif(p_request->>'organisation_id','') is not null then\n  created:=private.platform_create_club_need_for_record(p_tenant_id,p_actor_user_id,(p_request->>'organisation_id')::uuid,p_request->>'position',p_request->>'title',p_request->>'notes',nullif(p_request->>'expires_on','')::date);\n else\n  created:=public.platform_server_agency_create_club_need(p_tenant_id,p_actor_user_id,p_request->>'club_name',p_request->>'country',p_request->>'position',p_request->>'title',p_request->>'notes',nullif(p_request->>'expires_on','')::date);\n end if;\n perform private.platform_club_need_brief_patch(p_tenant_id,(created->>'club_need_id')::uuid,brief||jsonb_build_object('source_status',coalesce(nullif(brief->>'source_status',''),'unverified')));\n insert into platform.audit_events(tenant_id,actor_user_id,actor_kind,action,entity_type,entity_id,after_state,metadata) values(p_tenant_id,p_actor_user_id,'user','platform.agency.club_need_brief_recorded','club_need',created->>'club_need_id',brief,jsonb_build_object('source','agency_workspace'));\n return created||jsonb_build_object('brief_version',1);\nend $function$\n"}, {"signature": "public.redream_club_need_patch(uuid,timestamptz,jsonb)", "hash": "f8ade62847f20b192b43e23a75269f0a", "definition": "CREATE OR REPLACE FUNCTION public.redream_club_need_patch(p_need_id uuid, p_expected_updated_at timestamp with time zone, p_patch jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare n djm_os.club_needs%rowtype; result jsonb;\nbegin\n select * into n from djm_os.club_needs where id=p_need_id and archived_at is null for update;\n if not found or not private.user_is_tenant_admin(n.tenant_id,auth.uid()) or n.tenant_id is distinct from private.redream_request_tenant() then raise exception 'This club request is unavailable' using errcode='42501'; end if;\n if p_expected_updated_at is null or p_expected_updated_at is distinct from n.updated_at then raise exception 'This request has changed. Close and reopen it before editing again'; end if;\n if jsonb_typeof(p_patch) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_patch) k where k not in ('title','position','profile_notes','expires_at','salary_budget','transfer_budget','currency','salary_period','salary_tax_basis','contract_months','contract_guaranteed','option_months','transfer_type','availability_notes','source_status','secondary_position','min_age','max_age','preferred_foot','min_height_cm','level_requirements','nationality_preferences','passport_requirements','registration_notes','foreign_player_notes','playing_style','source_person_id','source_organisation_id','received_on','priority','source_context')) then raise exception 'Refresh ReDream before editing this request'; end if;\n if (p_patch?'position' and coalesce(trim(p_patch->>'position'),'')='') or (p_patch?'title' and coalesce(trim(p_patch->>'title'),'')='') then raise exception 'Keep a title and position for this request'; end if;\n if length(p_patch->>'profile_notes')>4000 or length(p_patch->>'title')>200 or length(p_patch->>'position')>200 then raise exception 'Shorten the request details before saving'; end if;\n -- Date-only expiry means valid through that day, as in the create writer.\n if p_patch?'expires_at' and p_patch->>'expires_at'~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then\n  p_patch:=p_patch||jsonb_build_object('expires_at',(((p_patch->>'expires_at')::date+1)::timestamptz-interval '1 second')::text);\n end if;\n result:=public.djm_entity_patch_v1('club_need',p_need_id,p_patch);\n return result||jsonb_build_object('brief_version',1);\nend $function$\n"}, {"signature": "public.platform_server_demand_control_fast(uuid,integer)", "hash": "7fde3806aa6da4f17f2e91521cede813", "definition": "CREATE OR REPLACE FUNCTION public.platform_server_demand_control_fast(p_tenant_id uuid, p_limit integer DEFAULT 100)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nwith needs as (\n  select n.*,o.name club_name,o.country,o.city,o.league_name\n  from djm_os.club_needs n join djm_os.organisations o on o.id=n.organisation_id and o.tenant_id=n.tenant_id\n  where n.tenant_id=p_tenant_id and n.status='active' and (n.expires_at is null or n.expires_at>=now())\n  order by case n.need_type when 'confirmed' then 0 else 1 end,n.priority desc,n.expires_at nulls last,n.received_at desc\n  limit greatest(1,least(coalesce(p_limit,100),250))\n), candidate_rows as materialized (\n  select pm.club_need_id,pm.id player_match_id,pm.player_id,pm.status match_status,\n    pm.overall_score,pm.football_score,pm.commercial_score,pm.registration_score,pm.career_score,pm.access_score,\n    pm.reasoning,pm.updated_at match_updated_at,\n    coalesce(nullif(trim(p.preferred_name),''),nullif(trim(concat_ws(' ',p.first_name,p.last_name)),''),'Player') player_name,\n    public.platform_server_career_pursuit_gate(p_tenant_id,pm.id) gate\n  from djm_os.player_matches pm join needs n on n.id=pm.club_need_id\n  join public.players p on p.id=pm.player_id and p.tenant_id=pm.tenant_id\n  where pm.tenant_id=p_tenant_id and pm.status in ('suggested','reviewing','shortlisted','pitched','active')\n), candidate_agg as (\n  select c.club_need_id,\n    count(*)::int recorded_candidates,\n    count(*) filter(where c.gate->>'state' like 'open_%')::int career_open,\n    count(*) filter(where c.gate->>'state' like 'review_%')::int human_review,\n    count(*) filter(where not (c.gate->>'state' like 'open_%') and not (c.gate->>'state' like 'review_%'))::int held,\n    coalesce(jsonb_agg(jsonb_build_object(\n      'player_match_id',c.player_match_id,\n      'player_id',c.player_id,\n      'player_name',c.player_name,\n      'match_status',c.match_status,\n      'overall_score',c.overall_score,\n      'football_score',c.football_score,\n      'commercial_score',c.commercial_score,\n      'registration_score',c.registration_score,\n      'career_score',c.career_score,\n      'access_score',c.access_score,\n      'reasoning',coalesce(c.reasoning,'{}'::jsonb),\n      'career_gate_state',c.gate->>'state',\n      'career_gate_reason',c.gate->>'reason'\n    ) order by\n      case when c.gate->>'state' like 'open_%' then 0 when c.gate->>'state' like 'review_%' then 1 else 2 end,\n      c.overall_score desc nulls last,\n      c.football_score desc nulls last,\n      case c.match_status when 'active' then 0 when 'pitched' then 1 when 'shortlisted' then 2 when 'reviewing' then 3 else 4 end,\n      c.match_updated_at desc,\n      c.player_name\n    ),'[]'::jsonb) candidates\n  from candidate_rows c group by c.club_need_id\n), direct_access as (\n  select distinct on (e.organisation_id) e.organisation_id,r.access_score,r.strength_score,r.trust_score,r.last_meaningful_at,p.full_name contact_name,e.role_title,r.team_member_id\n  from djm_os.relationships r join djm_os.employments e on e.tenant_id=r.tenant_id and e.person_id=r.person_id and e.is_current=true\n  join djm_os.people p on p.tenant_id=r.tenant_id and p.id=r.person_id\n  where r.tenant_id=p_tenant_id\n  order by e.organisation_id,r.access_score desc nulls last,r.strength_score desc nulls last,r.last_meaningful_at desc nulls last\n), base as (\n  select n.*,coalesce(c.recorded_candidates,0) recorded_candidates,coalesce(c.career_open,0) career_open,coalesce(c.human_review,0) human_review,coalesce(c.held,0) held,coalesce(c.candidates,'[]'::jsonb) candidates,\n    coalesce(d.access_score,0)::int direct_score,coalesce(d.strength_score,0)::int direct_strength,d.contact_name,d.role_title,d.team_member_id,\n    case when coalesce(d.access_score,0)<70 then public.platform_server_introduction_routes(p_tenant_id,n.organisation_id,1) else null end intro\n  from needs n left join candidate_agg c on c.club_need_id=n.id left join direct_access d on d.organisation_id=n.organisation_id\n), classified as (\n  select b.*,\n    coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0) intro_score,\n    case when b.direct_score>=70 then 'direct_route'\n         when coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>=70 and coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>=b.direct_score+10 then 'warm_introduction'\n         when b.direct_score>0 then 'developing_direct_route'\n         when coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>0 then 'developing_introduction'\n         else 'no_recorded_route' end access_mode,\n    case when b.recorded_candidates=0 then 'roster_gap'\n         when b.career_open=0 and b.human_review>0 then 'career_or_human_review_required'\n         when b.career_open=0 then 'career_blocked'\n         when b.direct_score>=70 then 'ready_direct'\n         when coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>=70 and coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>=b.direct_score+10 then 'ready_via_introduction'\n         else 'access_gap' end coverage_state\n  from base b\n), ranked as (\n  select c.*,row_number() over(order by case c.need_type when 'confirmed' then 0 else 1 end,\n    case c.coverage_state when 'ready_direct' then 1 when 'ready_via_introduction' then 2 when 'access_gap' then 3 when 'career_or_human_review_required' then 4 when 'career_blocked' then 5 when 'roster_gap' then 6 else 9 end,\n    c.priority desc,c.expires_at nulls last,c.club_name,c.title) rn\n  from classified c\n), items as (\n  select r.*,case r.coverage_state\n    when 'roster_gap' then jsonb_build_object('action_type','scout_or_recruit_for_need','instruction','No recorded roster match exists for this active club need. Scout or recruit against the recorded profile rather than forcing an unsuitable player.','requires_human_input',true)\n    when 'career_or_human_review_required' then jsonb_build_object('action_type','resolve_pursuit_gate','instruction','A recorded candidate exists, but career-strategy or human review must be resolved before external escalation.','requires_human_input',true)\n    when 'career_blocked' then jsonb_build_object('action_type','resolve_player_strategy_control','instruction','Recorded candidates exist but none are open under the player career controls.','requires_human_input',true)\n    when 'ready_direct' then jsonb_build_object('action_type','open_deep_pursuit_review','instruction','A career-open candidate and strong direct route are recorded. Open the full pursuit review before any external pitch.','requires_human_input',true)\n    when 'ready_via_introduction' then jsonb_build_object('action_type','open_deep_pursuit_review','instruction','A career-open candidate exists and a warm introduction is the stronger route. Open the full pursuit review before using it.','requires_human_input',true)\n    else jsonb_build_object('action_type','build_club_access','instruction','A career-open candidate exists, but access is not yet strong enough. Build or source the route before spending the player relationship.','requires_human_input',true) end next_action\n  from ranked r\n)\nselect jsonb_build_object(\n  'available',true,'tenant_id',p_tenant_id,'generated_at',now(),\n  'summary',jsonb_build_object(\n    'active_needs',(select count(*) from items),\n    'ready_for_deep_pursuit_review',(select count(*) from items where coverage_state in ('ready_direct','ready_via_introduction')),\n    'roster_gaps',(select count(*) from items where coverage_state='roster_gap'),\n    'access_gaps',(select count(*) from items where coverage_state='access_gap'),\n    'career_or_human_review',(select count(*) from items where coverage_state in ('career_or_human_review_required','career_blocked'))\n  ),\n  'items',coalesce((select jsonb_agg(jsonb_build_object(\n    'command_rank',rn,'club_need_id',id,\n    'club',jsonb_build_object('organisation_id',organisation_id,'name',club_name,'country',country,'city',city,'league_name',league_name),\n    'need',jsonb_build_object('title',title,'position',position,'secondary_position',secondary_position,'preferred_foot',preferred_foot,'min_age',min_age,'max_age',max_age,'min_height_cm',min_height_cm,'transfer_type',transfer_type,'transfer_budget',transfer_budget::text,'salary_budget',salary_budget::text,'currency',currency,'salary_period',salary_period,'salary_tax_basis',salary_tax_basis,'profile_notes',profile_notes,'raw_request',raw_request,'source_context',source_context,'source_status',source_status,'availability_notes',availability_notes,'contract_months',contract_months,'contract_guaranteed',contract_guaranteed,'option_months',option_months,'updated_at',updated_at,'level_requirements',level_requirements,'nationality_preferences',nationality_preferences,'passport_requirements',passport_requirements,'registration_notes',registration_notes,'foreign_player_notes',foreign_player_notes,'playing_style',playing_style,'source_person_id',source_person_id,'source_organisation_id',source_organisation_id,'received_on',case when received_date_confirmed then to_char(received_at,'YYYY-MM-DD') else null end,'source_person_name',(select p.full_name from djm_os.people p where p.id=source_person_id and p.tenant_id=p_tenant_id and p.archived_at is null),'source_organisation_name',(select o.name from djm_os.organisations o where o.id=source_organisation_id and o.tenant_id=p_tenant_id and o.archived_at is null),'priority',priority,'need_type',need_type,'confidence',confidence,'prediction_probability',prediction_probability,'confirmed_at',confirmed_at,'expires_at',expires_at,'received_at',received_at),\n    'coverage_state',coverage_state,\n    'candidate_coverage',jsonb_build_object('recorded_candidates',recorded_candidates,'career_open',career_open,'human_review',human_review,'held',held,'candidates',candidates),\n    'access',jsonb_build_object('mode',access_mode,'direct_score',direct_score,'direct_strength',direct_strength,'best_direct_contact',contact_name,'best_direct_role',role_title,'team_member_id',team_member_id,'introduction_score',intro_score,'best_introduction_route',intro->'best_route'),\n    'next_action',next_action\n  ) order by rn) from items),'[]'::jsonb),\n  'principle','Use a compact demand-control pass for portfolio allocation, preserving player-career gates and recorded access. Open the deep pursuit model before an external pitch.',\n  'truth_contract',jsonb_build_object(\n    'demand','Confirmed and predicted needs remain distinct. Predicted need is not treated as confirmed club instruction.',\n    'candidate','Recorded candidates are existing player-match records; no new football fit is invented by this fast control.',\n    'career','Every recorded candidate still passes through the human-owned career pursuit gate.',\n    'access','Direct access uses the best recorded direct relationship. Warm-introduction logic is checked only when direct access is below the operating threshold.',\n    'deep_review','Fast demand control does not calculate full pursuit readiness or transfer probability. A ready state means the prerequisites for deep human review are recorded.'\n  )\n);\n$function$\n"}, {"signature": "public.platform_server_workspace_need_record(uuid,uuid,uuid)", "hash": "c04c6ecbdf94df2d0ebb30e7bed46b20", "definition": "CREATE OR REPLACE FUNCTION public.platform_server_workspace_need_record(p_tenant_id uuid, p_user_id uuid, p_need_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_result jsonb;\nbegin\n if p_tenant_id is null or p_user_id is null or not private.user_is_tenant_admin(p_tenant_id,p_user_id) then\n  raise exception 'tenant_admin_access_required' using errcode='42501';\n end if;\n with needs as (\n  select n.*,o.name club_name,o.country,o.city,o.league_name\n  from djm_os.club_needs n join djm_os.organisations o on o.id=n.organisation_id and o.tenant_id=n.tenant_id\n  where n.tenant_id=p_tenant_id and n.id=p_need_id and (to_jsonb(n)->>'archived_at') is null and (to_jsonb(o)->>'archived_at') is null\n  order by case n.need_type when 'confirmed' then 0 else 1 end,n.priority desc,n.expires_at nulls last,n.received_at desc\n\n), candidate_rows as materialized (\n  select pm.club_need_id,pm.id player_match_id,pm.player_id,pm.status match_status,\n    pm.overall_score,pm.football_score,pm.commercial_score,pm.registration_score,pm.career_score,pm.access_score,\n    pm.reasoning,pm.updated_at match_updated_at,\n    coalesce(nullif(trim(p.preferred_name),''),nullif(trim(concat_ws(' ',p.first_name,p.last_name)),''),'Player') player_name,\n    public.platform_server_career_pursuit_gate(p_tenant_id,pm.id) gate\n  from djm_os.player_matches pm join needs n on n.id=pm.club_need_id\n  join public.players p on p.id=pm.player_id and p.tenant_id=pm.tenant_id\n  where pm.tenant_id=p_tenant_id and p.archived_at is null and coalesce(p.football_status,'active')<>'retired' and pm.status in ('suggested','reviewing','shortlisted','pitched','active')\n), candidate_agg as (\n  select c.club_need_id,\n    count(*)::int recorded_candidates,\n    count(*) filter(where c.gate->>'state' like 'open_%')::int career_open,\n    count(*) filter(where c.gate->>'state' like 'review_%')::int human_review,\n    count(*) filter(where not (c.gate->>'state' like 'open_%') and not (c.gate->>'state' like 'review_%'))::int held,\n    coalesce(jsonb_agg(jsonb_build_object(\n      'player_match_id',c.player_match_id,\n      'player_id',c.player_id,\n      'player_name',c.player_name,\n      'match_status',c.match_status,\n      'overall_score',c.overall_score,\n      'football_score',c.football_score,\n      'commercial_score',c.commercial_score,\n      'registration_score',c.registration_score,\n      'career_score',c.career_score,\n      'access_score',c.access_score,\n      'reasoning',coalesce(c.reasoning,'{}'::jsonb),\n      'career_gate_state',c.gate->>'state',\n      'career_gate_reason',c.gate->>'reason'\n    ) order by\n      case when c.gate->>'state' like 'open_%' then 0 when c.gate->>'state' like 'review_%' then 1 else 2 end,\n      c.overall_score desc nulls last,\n      c.football_score desc nulls last,\n      case c.match_status when 'active' then 0 when 'pitched' then 1 when 'shortlisted' then 2 when 'reviewing' then 3 else 4 end,\n      c.match_updated_at desc,\n      c.player_name\n    ),'[]'::jsonb) candidates\n  from candidate_rows c group by c.club_need_id\n), direct_access as (\n  select distinct on (e.organisation_id) e.organisation_id,r.access_score,r.strength_score,r.trust_score,r.last_meaningful_at,p.full_name contact_name,e.role_title,r.team_member_id\n  from djm_os.relationships r join djm_os.employments e on e.tenant_id=r.tenant_id and e.person_id=r.person_id and e.is_current=true\n  join djm_os.people p on p.tenant_id=r.tenant_id and p.id=r.person_id\n  where r.tenant_id=p_tenant_id\n  order by e.organisation_id,r.access_score desc nulls last,r.strength_score desc nulls last,r.last_meaningful_at desc nulls last\n), base as (\n  select n.*,coalesce(c.recorded_candidates,0) recorded_candidates,coalesce(c.career_open,0) career_open,coalesce(c.human_review,0) human_review,coalesce(c.held,0) held,coalesce(c.candidates,'[]'::jsonb) candidates,\n    coalesce(d.access_score,0)::int direct_score,coalesce(d.strength_score,0)::int direct_strength,d.contact_name,d.role_title,d.team_member_id,\n    case when coalesce(d.access_score,0)<70 then public.platform_server_introduction_routes(p_tenant_id,n.organisation_id,1) else null end intro\n  from needs n left join candidate_agg c on c.club_need_id=n.id left join direct_access d on d.organisation_id=n.organisation_id\n), classified as (\n  select b.*,\n    coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0) intro_score,\n    case when b.direct_score>=70 then 'direct_route'\n         when coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>=70 and coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>=b.direct_score+10 then 'warm_introduction'\n         when b.direct_score>0 then 'developing_direct_route'\n         when coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>0 then 'developing_introduction'\n         else 'no_recorded_route' end access_mode,\n    case when b.recorded_candidates=0 then 'roster_gap'\n         when b.career_open=0 and b.human_review>0 then 'career_or_human_review_required'\n         when b.career_open=0 then 'career_blocked'\n         when b.direct_score>=70 then 'ready_direct'\n         when coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>=70 and coalesce((b.intro#>>'{best_route,introduction_score}')::integer,0)>=b.direct_score+10 then 'ready_via_introduction'\n         else 'access_gap' end coverage_state\n  from base b\n), ranked as (\n  select c.*,row_number() over(order by case c.need_type when 'confirmed' then 0 else 1 end,\n    case c.coverage_state when 'ready_direct' then 1 when 'ready_via_introduction' then 2 when 'access_gap' then 3 when 'career_or_human_review_required' then 4 when 'career_blocked' then 5 when 'roster_gap' then 6 else 9 end,\n    c.priority desc,c.expires_at nulls last,c.club_name,c.title) rn\n  from classified c\n), items as (\n  select r.*,case r.coverage_state\n    when 'roster_gap' then jsonb_build_object('action_type','scout_or_recruit_for_need','instruction','No recorded roster match exists for this active club need. Scout or recruit against the recorded profile rather than forcing an unsuitable player.','requires_human_input',true)\n    when 'career_or_human_review_required' then jsonb_build_object('action_type','resolve_pursuit_gate','instruction','A recorded candidate exists, but career-strategy or human review must be resolved before external escalation.','requires_human_input',true)\n    when 'career_blocked' then jsonb_build_object('action_type','resolve_player_strategy_control','instruction','Recorded candidates exist but none are open under the player career controls.','requires_human_input',true)\n    when 'ready_direct' then jsonb_build_object('action_type','open_deep_pursuit_review','instruction','A career-open candidate and strong direct route are recorded. Open the full pursuit review before any external pitch.','requires_human_input',true)\n    when 'ready_via_introduction' then jsonb_build_object('action_type','open_deep_pursuit_review','instruction','A career-open candidate exists and a warm introduction is the stronger route. Open the full pursuit review before using it.','requires_human_input',true)\n    else jsonb_build_object('action_type','build_club_access','instruction','A career-open candidate exists, but access is not yet strong enough. Build or source the route before spending the player relationship.','requires_human_input',true) end next_action\n  from ranked r\n)\nselect jsonb_build_object(\n  'available',true,'tenant_id',p_tenant_id,'generated_at',now(),\n  'summary',jsonb_build_object(\n    'active_needs',(select count(*) from items),\n    'ready_for_deep_pursuit_review',(select count(*) from items where coverage_state in ('ready_direct','ready_via_introduction')),\n    'roster_gaps',(select count(*) from items where coverage_state='roster_gap'),\n    'access_gaps',(select count(*) from items where coverage_state='access_gap'),\n    'career_or_human_review',(select count(*) from items where coverage_state in ('career_or_human_review_required','career_blocked'))\n  ),\n  'items',coalesce((select jsonb_agg(jsonb_build_object(\n    'command_rank',rn,'club_need_id',id,\n    'club',jsonb_build_object('organisation_id',organisation_id,'name',club_name,'country',country,'city',city,'league_name',league_name),\n    'need',jsonb_build_object('status',status,'title',title,'position',position,'secondary_position',secondary_position,'preferred_foot',preferred_foot,'min_age',min_age,'max_age',max_age,'min_height_cm',min_height_cm,'transfer_type',transfer_type,'transfer_budget',transfer_budget::text,'salary_budget',salary_budget::text,'currency',currency,'salary_period',salary_period,'salary_tax_basis',salary_tax_basis,'profile_notes',profile_notes,'raw_request',raw_request,'source_context',source_context,'source_status',source_status,'availability_notes',availability_notes,'contract_months',contract_months,'contract_guaranteed',contract_guaranteed,'option_months',option_months,'updated_at',updated_at,'level_requirements',level_requirements,'nationality_preferences',nationality_preferences,'passport_requirements',passport_requirements,'registration_notes',registration_notes,'foreign_player_notes',foreign_player_notes,'playing_style',playing_style,'source_person_id',source_person_id,'source_organisation_id',source_organisation_id,'received_on',case when received_date_confirmed then to_char(received_at,'YYYY-MM-DD') else null end,'source_person_name',(select p.full_name from djm_os.people p where p.id=source_person_id and p.tenant_id=p_tenant_id and p.archived_at is null),'source_organisation_name',(select o.name from djm_os.organisations o where o.id=source_organisation_id and o.tenant_id=p_tenant_id and o.archived_at is null),'priority',priority,'need_type',need_type,'confidence',confidence,'prediction_probability',prediction_probability,'confirmed_at',confirmed_at,'expires_at',expires_at,'received_at',received_at),\n    'coverage_state',coverage_state,\n    'candidate_coverage',jsonb_build_object('recorded_candidates',recorded_candidates,'career_open',career_open,'human_review',human_review,'held',held,'candidates',candidates),\n    'access',jsonb_build_object('mode',access_mode,'direct_score',direct_score,'direct_strength',direct_strength,'best_direct_contact',contact_name,'best_direct_role',role_title,'team_member_id',team_member_id,'introduction_score',intro_score,'best_introduction_route',intro->'best_route'),\n    'next_action',case when status='active' and (expires_at is null or expires_at>=now()) then next_action else null end\n  ) order by rn) from items),'[]'::jsonb),\n  'principle','Use a compact demand-control pass for portfolio allocation, preserving player-career gates and recorded access. Open the deep pursuit model before an external pitch.',\n  'truth_contract',jsonb_build_object(\n    'demand','Confirmed and predicted needs remain distinct. Predicted need is not treated as confirmed club instruction.',\n    'candidate','Recorded candidates are existing player-match records; no new football fit is invented by this fast control.',\n    'career','Every recorded candidate still passes through the human-owned career pursuit gate.',\n    'access','Direct access uses the best recorded direct relationship. Warm-introduction logic is checked only when direct access is below the operating threshold.',\n    'deep_review','Fast demand control does not calculate full pursuit readiness or transfer probability. A ready state means the prerequisites for deep human review are recorded.'\n  )\n) into v_result;\n return jsonb_build_object('available',jsonb_array_length(v_result->'items')>0,'item',v_result#>'{items,0}');\nend;\n$function$\n"}, {"signature": "private.platform_server_agency_ensure_club(uuid,text,text)", "hash": "31b5b8ed1c95a850568c57bf7b930b59", "definition": "CREATE OR REPLACE FUNCTION private.platform_server_agency_ensure_club(p_tenant_id uuid, p_name text, p_country text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare\n  v_name text := nullif(btrim(coalesce(p_name, '')), '');\n  v_country text := nullif(btrim(coalesce(p_country, '')), '');\n  v_id uuid;\nbegin\n  if p_tenant_id is null or v_name is null or length(v_name) < 2 then\n    raise exception 'club_name_required';\n  end if;\n\n  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||lower(v_name),0));\n  if exists(select 1 from djm_os.organisations o where o.tenant_id=p_tenant_id and o.organisation_type='club' and o.archived_at is not null and lower(btrim(o.name))=lower(v_name)) and not exists(select 1 from djm_os.organisations o where o.tenant_id=p_tenant_id and o.organisation_type='club' and o.archived_at is null and lower(btrim(o.name))=lower(v_name)) then raise exception 'This club is archived. Choose an active club record';end if;\n  if (select count(*) from djm_os.organisations o where o.tenant_id=p_tenant_id and o.organisation_type='club' and o.archived_at is null and lower(btrim(o.name))=lower(v_name))>1 then raise exception 'More than one club has this name. Choose the existing club record';end if;\n  select o.id\n  into v_id\n  from djm_os.organisations o\n  where o.tenant_id = p_tenant_id\n    and o.organisation_type = 'club'\n    and o.archived_at is null\n      and lower(btrim(o.name)) = lower(v_name)\n  order by o.created_at\n  limit 1;\n\n  if v_id is null then\n    begin\n      insert into djm_os.organisations (\n        tenant_id,\n        name,\n        organisation_type,\n        country,\n        canonical_key\n      )\n      values (\n        p_tenant_id,\n        v_name,\n        'club',\n        v_country,\n        null\n      )\n      returning id into v_id;\n    exception\n      when unique_violation then\n        select o.id\n        into v_id\n        from djm_os.organisations o\n        where o.tenant_id = p_tenant_id\n          and o.organisation_type = 'club'\n          and o.archived_at is null\n      and lower(btrim(o.name)) = lower(v_name)\n        order by o.created_at\n        limit 1;\n    end;\n  elsif v_country is not null then\n    update djm_os.organisations\n    set country = coalesce(country, v_country),\n        updated_at = now()\n    where id = v_id\n      and tenant_id = p_tenant_id;\n  end if;\n\n  if v_id is null then\n    raise exception 'club_create_failed';\n  end if;\n\n  return v_id;\nend;\n$function$\n"}]$spec$::jsonb) loop
  routine:=to_regprocedure(spec->>'signature');
  if not exists(select 1 from pg_proc where oid=routine and md5(prosrc)=spec->>'hash') then raise exception 'Unreviewed intake contract %',spec->>'signature';end if;
  execute spec->>'definition';
 end loop;
end $patch$;
commit;
